<?php

defined('BASEPATH') or exit('No direct script access allowed');
class Company_tickets extends AdminController
{
    public function index()
    {
        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}
        require_once APPPATH.'services/CompanyTickets.php';require_once APPPATH.'services/CompanyOperationFiles.php';require_once APPPATH.'services/CompanyOperationFilesHttp.php';require_once APPPATH.'services/CompanyOperationalPortalAdmin.php';require_once APPPATH.'services/CompanySupportAuthorship.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$acl=new IssuerResourceAccess($this->db,db_prefix());if(!$acl->can($issuer,$actor,'tickets','view')){show_error('Sem permissão para suporte desta empresa.',403);return;}
        $this->output->set_header('Cache-Control: no-store');$csrf=$this->session->userdata('company_tickets_csrf');if(!is_string($csrf)||strlen($csrf)!==64){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_tickets_csrf',$csrf);}
        $s=new CompanyTickets($this->db,db_prefix());$files=new CompanyOperationFiles($this->db,db_prefix());$operation_files=[];$portal_controls=null;$support_authorship=null;$error=null;$ticket=null;$directory=['items'=>[],'next'=>null];$clients=[];$staff=[];
        try{
            if($this->input->method(true)==='POST'){
                $token=$this->input->post('company_tickets_csrf',false);if(!is_string($token)||!hash_equals($csrf,$token)){show_error('Recarregue antes de salvar.',403);return;}$action=$this->input->post('action',false);$key=$this->input->post('request_key',false);if(!is_string($key))throw new DomainException('company_operation_invalid_input');$id=$this->input->post('ticket_id',false);$rev=$this->input->post('revision',false);
                if(CompanyOperationalPortalAdmin::handle($this,$issuer,$actor,'tickets',$action,$id,$rev,$key)){}
                elseif($action==='file_upload'){[$name,$bytes]=CompanyOperationFilesHttp::upload();$id=$files->upload($issuer,$actor,'ticket',$id,$rev,$key,$name,$bytes);}
                elseif($action==='file_hide'){$file=$this->input->post('file_key',false);if(!is_string($file))throw new DomainException('company_operation_file_invalid');$id=$files->hide($issuer,$actor,'ticket',$id,$rev,$file,$key);}
                elseif($action==='create'){$input=$this->input->post('ticket',false);if(!is_array($input))throw new DomainException('company_operation_invalid_input');$id=$s->create($issuer,$actor,$input,$key);}
                elseif($action==='reply'){$body=$this->input->post('reply',false);if(!is_string($body))throw new DomainException('company_operation_invalid_input');$id=$s->reply($issuer,$actor,$id,$rev,$body,$key);}
                elseif($action==='change'){$status=$this->input->post('status',false);$priority=$this->input->post('priority',false);if(!is_string($status)||!is_string($priority))throw new DomainException('company_operation_invalid_input');$id=$s->change($issuer,$actor,$id,$rev,$this->input->post('assignee_id',false),$status,$priority,$key);}
                else throw new DomainException('company_operation_invalid_input');CompanyRequestScope::invalidateCaches($this);redirect(CompanyRequestScope::adminUrl($this,'company_tickets?ticket='.(int)$id),'location',303);return;
            }elseif(!in_array($this->input->method(true),['GET','HEAD'],true)){show_error('Método não permitido.',405);return;}
            $id=$this->input->get('ticket',false);$fileKey=$this->input->get('file',false);if($fileKey!==null){if(!is_string($fileKey))throw new DomainException('company_operation_file_invalid');CompanyOperationFilesHttp::respond($this,$files->file($issuer,$actor,'ticket',$id,$fileKey));return;}if($id!==null)$ticket=$s->get($issuer,$actor,$id);if($ticket!==null)$support_authorship=(new CompanySupportAuthorship($this->db,db_prefix()))->get($issuer,$actor,$id);if($ticket!==null)$operation_files=$files->page($issuer,$actor,'ticket',$id);if($ticket!==null)$portal_controls=CompanyOperationalPortalAdmin::controls($this,$issuer,$actor,'tickets',$ticket);$directory=$s->page($issuer,$actor,$this->input->get('after',false)??0,(string)($this->input->get('search',false)??''));$staff=$s->staffOptions($issuer,$actor);if($acl->can($issuer,$actor,'customers','view'))$clients=(new CompanyClients($this->db,db_prefix()))->page($issuer,$actor,0,100,(string)($this->input->get('client_search',false)??''))['items'];
        }catch(DomainException $e){$this->output->set_status_header(409);$error=match($e->getMessage()){'company_operation_stale'=>'O chamado mudou. Reabra antes de salvar.','company_ticket_closed'=>'Reabra o chamado antes de registrar nova mensagem.',default=>'Dados, referências ou permissões inválidos. Nenhuma alteração foi confirmada.'};}catch(Throwable $e){log_message('error','Company ticket operation unconfirmed; no contents logged.');$this->output->set_status_header(503);$error='Não foi possível confirmar a operação. Reabra antes de tentar novamente.';}
        $this->load->view('admin/companies/tickets',['issuer'=>$issuer,'actor'=>$actor,'support_authorship'=>$support_authorship,'operation_files'=>$operation_files,'portal_controls'=>$portal_controls,'ticket'=>$ticket,'directory'=>$directory,'clients'=>$clients,'staff_options'=>$staff,'error'=>$error,'company_tickets_csrf'=>$csrf,'request_key'=>bin2hex(random_bytes(32)),'can_create'=>$acl->can($issuer,$actor,'tickets','create'),'can_edit'=>$acl->can($issuer,$actor,'tickets','edit')]);
    }
}
